insert into public.tests (id, number, title, format_month, format_year, is_new, is_free, is_pro, content)
values ('t10', 10, 'Mock Test #10', 7, 2026, false, true, false, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":3,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some short conversations. Choose the correct answer.","durationSec":155,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"What will the man do this evening?","options":[{"key":"A","text":"Watch a match"},{"key":"B","text":"Visit his parents"},{"key":"C","text":"Study for a test"}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"Which floor is the office on?","options":[{"key":"A","text":"The second"},{"key":"B","text":"The fourth"},{"key":"C","text":"The fifth"}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"What does the woman order?","options":[{"key":"A","text":"Green tea"},{"key":"B","text":"Black coffee"},{"key":"C","text":"Orange juice"}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"Why can’t the man come to the meeting?","options":[{"key":"A","text":"He is ill"},{"key":"B","text":"He has another meeting"},{"key":"C","text":"His car broke down"}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"What present will they buy for Kamola?","options":[{"key":"A","text":"A book"},{"key":"B","text":"A scarf"},{"key":"C","text":"A watch"}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"When does the library close today?","options":[{"key":"A","text":"At 6 pm"},{"key":"B","text":"At 8 pm"},{"key":"C","text":"At 9 pm"}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"What sport does the girl play?","options":[{"key":"A","text":"Tennis"},{"key":"B","text":"Volleyball"},{"key":"C","text":"Basketball"}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"How much does the man pay?","options":[{"key":"A","text":"12,000 sum"},{"key":"B","text":"15,000 sum"},{"key":"C","text":"18,000 sum"}]}],"audio":"t10/l1.mp3","audioAt":{"1":8,"2":26,"3":48,"4":62,"5":79,"6":99,"7":118,"8":135}},{"id":"l2","index":2,"title":"Evergreen Hotel — Room Booking","instruction":"Complete the notes. Write","emphasis":"no more than two words","durationSec":81,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"Type of room:"},{"id":"l-10","number":10,"kind":"gap","prompt":"Arrival date: 14"},{"id":"l-11","number":11,"kind":"gap","prompt":"Number of nights:"},{"id":"l-12","number":12,"kind":"gap","prompt":"Price per night: $"},{"id":"l-13","number":13,"kind":"gap","prompt":"Breakfast is served in the"},{"id":"l-14","number":14,"kind":"gap","prompt":"Guest wants a room with a"},{"id":"l-15","number":15,"kind":"gap","prompt":"Airport pick-up costs $"},{"id":"l-16","number":16,"kind":"gap","prompt":"Confirmation will be sent by"}],"audio":"t10/l2.mp3","audioAt":{"9":17,"10":20,"11":29,"12":33,"13":43,"14":49,"15":60,"16":68}},{"id":"l3","index":3,"instruction":"You will hear six people talking about how they learn English. Choose the correct answer.","durationSec":89,"questions":[{"id":"l-17","number":17,"kind":"mcq","prompt":"Speaker 1 improves her English mainly by","options":[{"key":"A","text":"reading novels"},{"key":"B","text":"watching films"},{"key":"C","text":"using apps"}]},{"id":"l-18","number":18,"kind":"mcq","prompt":"Speaker 2 finds it hardest to","options":[{"key":"A","text":"understand native speakers"},{"key":"B","text":"write essays"},{"key":"C","text":"remember new words"}]},{"id":"l-19","number":19,"kind":"mcq","prompt":"Speaker 3 practises speaking with","options":[{"key":"A","text":"a private teacher"},{"key":"B","text":"online partners"},{"key":"C","text":"his colleagues"}]},{"id":"l-20","number":20,"kind":"mcq","prompt":"Speaker 4 needs English for","options":[{"key":"A","text":"university"},{"key":"B","text":"her job"},{"key":"C","text":"travelling"}]},{"id":"l-21","number":21,"kind":"mcq","prompt":"Speaker 5 says grammar books are","options":[{"key":"A","text":"boring"},{"key":"B","text":"very useful"},{"key":"C","text":"too expensive"}]},{"id":"l-22","number":22,"kind":"mcq","prompt":"Speaker 6 plans to","options":[{"key":"A","text":"take an exam"},{"key":"B","text":"study abroad"},{"key":"C","text":"become a teacher"}]}],"audio":"t10/l3.mp3","audioAt":{"17":10,"18":21,"19":36,"20":49,"21":62,"22":73}},{"id":"l4","index":4,"instruction":"Listen to a radio interview with a chef. Choose the correct answer.","durationSec":77,"questions":[{"id":"l-23","number":23,"kind":"mcq","prompt":"The chef decided to cook professionally","options":[{"key":"A","text":"after school"},{"key":"B","text":"after working in a bank"},{"key":"C","text":"after a trip abroad"}]},{"id":"l-24","number":24,"kind":"mcq","prompt":"Her restaurant is famous for","options":[{"key":"A","text":"national dishes"},{"key":"B","text":"seafood"},{"key":"C","text":"desserts"}]},{"id":"l-25","number":25,"kind":"mcq","prompt":"Most of her vegetables come from","options":[{"key":"A","text":"the market"},{"key":"B","text":"local farmers"},{"key":"C","text":"her own garden"}]},{"id":"l-26","number":26,"kind":"mcq","prompt":"She says the most important skill for a chef is","options":[{"key":"A","text":"creativity"},{"key":"B","text":"speed"},{"key":"C","text":"organisation"}]},{"id":"l-27","number":27,"kind":"mcq","prompt":"Next year she plans to","options":[{"key":"A","text":"open a second restaurant"},{"key":"B","text":"write a cookbook"},{"key":"C","text":"start a cooking school"}]}],"audio":"t10/l4.mp3","audioAt":{"23":18,"24":28,"25":41,"26":53,"27":65}},{"id":"l5","index":5,"title":"Science Centre — School Visit","instruction":"Complete the notes. Write","emphasis":"one word or a number","durationSec":33,"questions":[{"id":"l-28","number":28,"kind":"gap","prompt":"Students leave their bags in the"},{"id":"l-29","number":29,"kind":"gap","prompt":"The planetarium show lasts (minutes):"},{"id":"l-30","number":30,"kind":"gap","prompt":"Lunch is in the"}],"audio":"t10/l5.mp3","audioAt":{"28":9,"29":16,"30":22}},{"id":"l6","index":6,"instruction":"Listen to a talk about saving money. Choose the correct answer.","durationSec":70,"questions":[{"id":"l-31","number":31,"kind":"mcq","prompt":"According to the speaker, most people fail to save because they","options":[{"key":"A","text":"earn too little"},{"key":"B","text":"do not plan"},{"key":"C","text":"spend on travel"}]},{"id":"l-32","number":32,"kind":"mcq","prompt":"The speaker suggests saving","options":[{"key":"A","text":"10% of income"},{"key":"B","text":"25% of income"},{"key":"C","text":"whatever is left"}]},{"id":"l-33","number":33,"kind":"mcq","prompt":"The best time to save is","options":[{"key":"A","text":"at the end of the month"},{"key":"B","text":"on payday"},{"key":"C","text":"every Friday"}]},{"id":"l-34","number":34,"kind":"mcq","prompt":"Small daily purchases are described as","options":[{"key":"A","text":"harmless"},{"key":"B","text":"surprisingly expensive"},{"key":"C","text":"necessary"}]},{"id":"l-35","number":35,"kind":"mcq","prompt":"The speaker’s final advice is to","options":[{"key":"A","text":"use cash only"},{"key":"B","text":"track spending"},{"key":"C","text":"open several accounts"}]}],"audio":"t10/l6.mp3","audioAt":{"31":7,"32":20,"33":32,"34":44,"35":54}}],"reading":[{"id":"r1","index":1,"title":"Notice: Green City Cleaning Day","instruction":"Read the text and fill in the gaps. Write one word only.","passage":[{"label":"A","text":"Join us for Green City Cleaning Day on Sunday, 22 April! Volunteers will meet at 9 am outside the town hall and work until lunchtime."},{"label":"B","text":"Gloves and rubbish bags will be provided, but please wear old clothes and comfortable shoes. Bring a bottle of water, as it may be hot."},{"label":"C","text":"After the event, all volunteers are invited to a free lunch in the town hall garden. Children must come with a parent."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"Volunteers meet outside the town"},{"id":"r-2","number":2,"kind":"gap","prompt":"The work continues until"},{"id":"r-3","number":3,"kind":"gap","prompt":"Organisers will give volunteers gloves and"},{"id":"r-4","number":4,"kind":"gap","prompt":"Volunteers should wear old"},{"id":"r-5","number":5,"kind":"gap","prompt":"Everyone should bring some"},{"id":"r-6","number":6,"kind":"gap","prompt":"Lunch will be in the town hall"},{"id":"r-7","number":7,"kind":"gap","prompt":"Children need to be with a"}]},{"id":"r2","index":2,"title":"Short Messages","instruction":"Read the messages and choose the correct answer.","passage":[{"label":"A","text":"Hi Timur, I can’t make football practice tonight — I’ve got a job interview. Could you tell the coach? Thanks!"},{"label":"B","text":"Special offer: buy two pizzas and get a third one free. Valid only on Mondays and Tuesdays until the end of March."},{"label":"C","text":"Dear parents, the school trip to the zoo is postponed until next Friday because of the rain forecast. Please keep the permission forms."}],"questions":[{"id":"r-8","number":8,"kind":"mcq","prompt":"Why will the writer miss practice?","options":[{"key":"A","text":"He is ill"},{"key":"B","text":"He has a job interview"},{"key":"C","text":"He is travelling"}]},{"id":"r-9","number":9,"kind":"mcq","prompt":"What does the writer ask Timur to do?","options":[{"key":"A","text":"Tell the coach"},{"key":"B","text":"Pick him up"},{"key":"C","text":"Bring his kit"}]},{"id":"r-10","number":10,"kind":"mcq","prompt":"How many pizzas must you buy to get one free?","options":[{"key":"A","text":"One"},{"key":"B","text":"Two"},{"key":"C","text":"Three"}]},{"id":"r-11","number":11,"kind":"mcq","prompt":"On which days is the offer valid?","options":[{"key":"A","text":"At weekends"},{"key":"B","text":"Mondays and Tuesdays"},{"key":"C","text":"Every day"}]},{"id":"r-12","number":12,"kind":"mcq","prompt":"Why is the school trip postponed?","options":[{"key":"A","text":"The bus is broken"},{"key":"B","text":"The weather"},{"key":"C","text":"The zoo is closed"}]},{"id":"r-13","number":13,"kind":"mcq","prompt":"What should parents do with the forms?","options":[{"key":"A","text":"Sign them again"},{"key":"B","text":"Keep them"},{"key":"C","text":"Return them today"}]},{"id":"r-14","number":14,"kind":"mcq","prompt":"Which message is an advertisement?","options":[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"}]}]},{"id":"r3","index":3,"title":"Robots in the Kitchen","instruction":"Read the article and choose the correct answer.","passage":[{"label":"A","text":"Restaurants in several countries have started using robots to cook simple dishes such as burgers, noodles and salads."},{"label":"B","text":"Owners say robots never get tired and always follow the recipe exactly, which keeps the quality the same every day."},{"label":"C","text":"However, many customers still prefer food made by people. They say that cooking is an art, and that robots cannot add a personal touch."},{"label":"D","text":"For now, most experts agree that robots will help chefs rather than replace them, doing repetitive tasks such as chopping and frying."}],"questions":[{"id":"r-15","number":15,"kind":"mcq","prompt":"Robots are currently used to cook","options":[{"key":"A","text":"complex meals"},{"key":"B","text":"simple dishes"},{"key":"C","text":"desserts only"}]},{"id":"r-16","number":16,"kind":"mcq","prompt":"According to owners, robots","options":[{"key":"A","text":"are cheap to buy"},{"key":"B","text":"never get tired"},{"key":"C","text":"cook faster than people"}]},{"id":"r-17","number":17,"kind":"mcq","prompt":"Robots keep the quality","options":[{"key":"A","text":"the same"},{"key":"B","text":"higher"},{"key":"C","text":"lower"}]},{"id":"r-18","number":18,"kind":"mcq","prompt":"Many customers believe robots cannot","options":[{"key":"A","text":"cook quickly"},{"key":"B","text":"add a personal touch"},{"key":"C","text":"follow recipes"}]},{"id":"r-19","number":19,"kind":"mcq","prompt":"Experts think robots will","options":[{"key":"A","text":"replace chefs"},{"key":"B","text":"help chefs"},{"key":"C","text":"disappear soon"}]},{"id":"r-20","number":20,"kind":"mcq","prompt":"An example of a repetitive task is","options":[{"key":"A","text":"creating recipes"},{"key":"B","text":"chopping"},{"key":"C","text":"serving guests"}]},{"id":"r-21","number":21,"kind":"mcq","prompt":"The best title is","options":[{"key":"A","text":"Chefs Out of Work"},{"key":"B","text":"A Helping Hand in the Kitchen"},{"key":"C","text":"The Art of Cooking"}]}]},{"id":"r4","index":4,"title":"The Great Silk Road Today","instruction":"Do the following statements agree with the information in the text?","passage":[{"label":"A","text":"For more than 1,500 years, the Silk Road connected China with the Mediterranean, carrying not only silk but also spices, paper and ideas."},{"label":"B","text":"Cities such as Samarkand, Bukhara and Khiva grew rich as trading centres, and many of their famous buildings date from this period."},{"label":"C","text":"Today, the route is being revived through new railways and roads, and tourism along the old caravan routes has grown rapidly in the last ten years.","highlight":"tourism along the old caravan routes has grown rapidly"},{"label":"D","text":"Some historians, however, worry that fast development may damage ancient sites if they are not properly protected."}],"questions":[{"id":"r-22","number":22,"kind":"tfng","prompt":"The Silk Road carried only silk."},{"id":"r-23","number":23,"kind":"tfng","prompt":"Samarkand, Bukhara and Khiva became rich through trade."},{"id":"r-24","number":24,"kind":"tfng","prompt":"Tourism along the old routes has increased in recent years."},{"id":"r-25","number":25,"kind":"tfng","prompt":"Most tourists come from Europe."},{"id":"r-26","number":26,"kind":"tfng","prompt":"All historians support fast development of the route."}]},{"id":"r5","index":5,"title":"The Benefits of Boredom","instruction":"Read the text and choose the correct answer.","passage":[{"label":"A","text":"Most of us try to avoid boredom. As soon as we have a free minute, we reach for our phones."},{"label":"B","text":"Yet psychologists say boredom can be useful. When the mind has nothing to do, it starts to wander, and this often leads to new ideas."},{"label":"C","text":"In one experiment, people who first did a boring task, like copying phone numbers, later produced more creative answers than others."},{"label":"D","text":"Researchers suggest leaving small gaps in the day without screens, such as a walk or a bus ride, to give the brain time to rest and create."}],"questions":[{"id":"r-27","number":27,"kind":"mcq","prompt":"What do most people do when they feel bored?","options":[{"key":"A","text":"Go for a walk"},{"key":"B","text":"Use their phones"},{"key":"C","text":"Read a book"}]},{"id":"r-28","number":28,"kind":"mcq","prompt":"According to psychologists, boredom can","options":[{"key":"A","text":"cause stress"},{"key":"B","text":"lead to new ideas"},{"key":"C","text":"damage memory"}]},{"id":"r-29","number":29,"kind":"mcq","prompt":"In the experiment, the boring task was","options":[{"key":"A","text":"reading a text"},{"key":"B","text":"copying phone numbers"},{"key":"C","text":"waiting in a queue"}]},{"id":"r-30","number":30,"kind":"mcq","prompt":"After the boring task, people were more","options":[{"key":"A","text":"tired"},{"key":"B","text":"creative"},{"key":"C","text":"relaxed"}]},{"id":"r-31","number":31,"kind":"mcq","prompt":"Researchers recommend","options":[{"key":"A","text":"avoiding boredom"},{"key":"B","text":"short breaks without screens"},{"key":"C","text":"longer working hours"}]},{"id":"r-32","number":32,"kind":"mcq","prompt":"The word “wander” is closest to","options":[{"key":"A","text":"stop"},{"key":"B","text":"move freely"},{"key":"C","text":"focus"}]},{"id":"r-33","number":33,"kind":"mcq","prompt":"A bus ride is given as an example of","options":[{"key":"A","text":"a waste of time"},{"key":"B","text":"a gap without screens"},{"key":"C","text":"a boring job"}]},{"id":"r-34","number":34,"kind":"mcq","prompt":"The text mainly argues that boredom","options":[{"key":"A","text":"should be avoided"},{"key":"B","text":"has benefits"},{"key":"C","text":"is increasing"}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"The writer would probably agree that we should","options":[{"key":"A","text":"use phones less often"},{"key":"B","text":"work without breaks"},{"key":"C","text":"avoid free time"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1.1","kind":"Informal letter","context":"You attend English evening classes at a language centre. You have received this message from the centre:\n\n\"From next week, all evening classes will move from 6 pm to 8 pm, and the group size will increase from 10 to 18 students.\"","prompt":"Write a message to a classmate. Tell them about the changes and how you feel about them. Write about 50 words.","targetWords":50,"minWords":40},{"id":"w2","index":2,"label":"Task 1.2","kind":"Formal letter","context":"You attend English evening classes at a language centre. You have received this message from the centre:\n\n\"From next week, all evening classes will move from 6 pm to 8 pm, and the group size will increase from 10 to 18 students.\"","prompt":"Write a letter to the director of the language centre. Explain how the changes affect you and suggest a better solution. Write 120–150 words.","targetWords":135,"minWords":120},{"id":"w3","index":3,"label":"Task 2","kind":"Essay","prompt":"Many people believe that learning online is as effective as learning in a classroom. To what extent do you agree or disagree? Give reasons and examples. Write at least 180 words.","targetWords":200,"minWords":180}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"Tell me about your family.","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"What do you like to do in your free time?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"What kind of food do you enjoy most?","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: people working in a busy open-plan office · Picture B: a person working from home at a kitchen table","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Where would you prefer to work? Why?","image":"Picture A: people working in a busy open-plan office · Picture B: a person working from home at a kitchen table","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"Do you think more people will work from home in the future?","image":"Picture A: people working in a busy open-plan office · Picture B: a person working from home at a kitchen table","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe an important day in your life. Say when it was, what happened and why it was important to you.","image":"A young man celebrating his graduation with his family","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Tourism is good for a country. For: it creates jobs and brings money. Against: it damages nature and raises prices for local people. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
