values ('t10', $json${"l-1":{"answer":"C"},"l-2":{"answer":"B"},"l-3":{"answer":"A"},"l-4":{"answer":"A"},"l-5":{"answer":"B"},"l-6":{"answer":"A","explanation":"Odatda 8 da yopiladi, lekin bugun bayram oldidan 6 da."},"l-7":{"answer":"C"},"l-8":{"answer":"B","explanation":"18 ming emas: 3 ming chegirma bilan 15 ming."},"l-9":{"answer":"double room|double"},"l-10":{"answer":"October"},"l-11":{"answer":"three|3"},"l-12":{"answer":"70","explanation":"Avval 85 dollar deyiladi, keyin haftalik chegirma bilan 70."},"l-13":{"answer":"garden"},"l-14":{"answer":"balcony"},"l-15":{"answer":"20|twenty"},"l-16":{"answer":"text message|text"},"l-17":{"answer":"B"},"l-18":{"answer":"A"},"l-19":{"answer":"B"},"l-20":{"answer":"B"},"l-21":{"answer":"B"},"l-22":{"answer":"A"},"l-23":{"answer":"B"},"l-24":{"answer":"A"},"l-25":{"answer":"B"},"l-26":{"answer":"C"},"l-27":{"answer":"B"},"l-28":{"answer":"cloakroom"},"l-29":{"answer":"40|forty"},"l-30":{"answer":"canteen"},"l-31":{"answer":"B"},"l-32":{"answer":"A"},"l-33":{"answer":"B"},"l-34":{"answer":"B"},"l-35":{"answer":"B"},"r-1":{"answer":"hall"},"r-2":{"answer":"lunchtime|lunch"},"r-3":{"answer":"bags"},"r-4":{"answer":"clothes"},"r-5":{"answer":"water"},"r-6":{"answer":"garden"},"r-7":{"answer":"parent"},"r-8":{"answer":"B"},"r-9":{"answer":"A"},"r-10":{"answer":"B"},"r-11":{"answer":"B"},"r-12":{"answer":"B"},"r-13":{"answer":"B"},"r-14":{"answer":"B"},"r-15":{"answer":"B"},"r-16":{"answer":"B"},"r-17":{"answer":"A"},"r-18":{"answer":"B"},"r-19":{"answer":"B"},"r-20":{"answer":"B"},"r-21":{"answer":"B"},"r-22":{"answer":"False"},"r-23":{"answer":"True"},"r-24":{"answer":"True","explanation":"C paragrafi: \"has grown rapidly\"."},"r-25":{"answer":"Not given"},"r-26":{"answer":"False"},"r-27":{"answer":"B"},"r-28":{"answer":"B"},"r-29":{"answer":"B"},"r-30":{"answer":"B"},"r-31":{"answer":"B"},"r-32":{"answer":"B"},"r-33":{"answer":"B"},"r-34":{"answer":"B"},"r-35":{"answer":"A"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some short conversations. For each question, choose the correct answer."},{"voice":"narrator","text":"Question 1. What will the man do this evening?","question":1},{"voice":"woman","text":"Are you coming to watch the match with us tonight? Or are you visiting your parents?"},{"voice":"man","text":"Neither, unfortunately. I've got a big test tomorrow, so I'll be at home studying all evening."},{"voice":"narrator","text":"Question 2. Which floor is the office on?","question":2},{"voice":"man","text":"Excuse me, is Mr Aliev's office on the second floor?"},{"voice":"woman","text":"It used to be, but they moved last month. Take the lift to the fourth floor. It's the first door on the left. The fifth floor is the canteen."},{"voice":"narrator","text":"Question 3. What does the woman order?","question":3},{"voice":"man","text":"Black coffee as usual?"},{"voice":"woman","text":"Not today. I've had too much coffee this week. I'll have a green tea, please. No sugar."},{"voice":"narrator","text":"Question 4. Why can’t the man come to the meeting?","question":4},{"voice":"woman","text":"Are you coming to the meeting this afternoon? Is your car fixed?"},{"voice":"man","text":"The car's fine now, but I've got a terrible temperature. I think I'd better stay in bed today."},{"voice":"narrator","text":"Question 5. What present will they buy for Kamola?","question":5},{"voice":"woman","text":"Let's buy Kamola a book for her birthday."},{"voice":"man","text":"She's got hundreds of books. And a watch is too expensive. What about a warm scarf? Winter is coming."},{"voice":"woman","text":"Good idea. A scarf it is."},{"voice":"narrator","text":"Question 6. When does the library close today?","question":6},{"voice":"man","text":"The library closes at eight, right? I can study there after work."},{"voice":"woman","text":"Normally, yes, but it's a holiday tomorrow, so today it closes early, at six."},{"voice":"narrator","text":"Question 7. What sport does the girl play?","question":7},{"voice":"man","text":"Do you still play tennis, Madina?"},{"voice":"woman2","text":"I stopped last year. I tried volleyball, but now I play basketball for the school team. We train three times a week."},{"voice":"narrator","text":"Question 8. How much does the man pay?","question":8},{"voice":"man","text":"How much are these apples?"},{"voice":"woman","text":"Eighteen thousand sum for two kilos. But you're a regular customer, so I'll give you three thousand off. Fifteen thousand, please."},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a phone call to a hotel. Complete the notes. Write no more than two words."},{"voice":"woman","text":"Good morning, Evergreen Hotel."},{"voice":"man","text":"Good morning. I'd like to book a room for my wife and me."},{"voice":"woman","text":"Certainly. So that's a double room for two people.","question":9},{"voice":"woman","text":"When would you like to arrive?","question":10},{"voice":"man","text":"On the fourteenth of October. Not September, sorry, October."},{"voice":"woman","text":"And for how many nights?","question":11},{"voice":"man","text":"Three nights, please."},{"voice":"man","text":"How much is it per night?","question":12},{"voice":"woman","text":"The usual price is eighty-five dollars, but in October we have a special offer, so it's seventy dollars a night."},{"voice":"woman","text":"Breakfast is included. When the weather is good, we serve it in the garden. Otherwise it's in the restaurant.","question":13},{"voice":"man","text":"Wonderful. Could we have a room with a balcony? We love the view of the mountains.","question":14},{"voice":"woman","text":"No problem. I'll give you a room on the third floor."},{"voice":"man","text":"Do you offer an airport pick-up?","question":15},{"voice":"woman","text":"Yes, our driver can meet you. It costs twenty dollars each way."},{"voice":"woman","text":"I'll send you a confirmation by text message in a few minutes. We don't use email for bookings.","question":16},{"voice":"man","text":"Thank you very much."},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear six people talking about how they learn English. For each speaker, choose the correct answer."},{"voice":"narrator","text":"Speaker 1.","question":17},{"voice":"woman","text":"I've tried apps and I sometimes read, but what really works for me is films. I watch one every weekend with English subtitles."},{"voice":"narrator","text":"Speaker 2.","question":18},{"voice":"man","text":"Writing isn't a problem, and I remember new words quite easily. The hardest thing is understanding native speakers. They talk so fast!"},{"voice":"narrator","text":"Speaker 3.","question":19},{"voice":"man2","text":"A private teacher was too expensive for me, and nobody at work speaks English. So I found conversation partners online. We talk on video every evening."},{"voice":"narrator","text":"Speaker 4.","question":20},{"voice":"woman2","text":"I finished university years ago and I don't travel much. I need English for my job. I work for an international company and write emails every day."},{"voice":"narrator","text":"Speaker 5.","question":21},{"voice":"man3","text":"Many people say grammar books are boring, but I disagree. They're very useful. A good grammar book explains things clearly, step by step."},{"voice":"narrator","text":"Speaker 6.","question":22},{"voice":"woman3","text":"I don't want to study abroad or teach. My plan is to take the CEFR exam in December. I need a B2 certificate."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear a radio interview with a chef. Choose the correct answer."},{"voice":"man","text":"Today's guest is Nilufar, owner of one of the most popular restaurants in Tashkent. Nilufar, did you always want to be a chef?"},{"voice":"woman","text":"Not at all. After school I studied economics, and then I worked in a bank for six years. I was cooking for friends every weekend, and one day I decided to make it my job.","question":23},{"voice":"woman","text":"We serve some international food, and our desserts are nice, but people really come for our national dishes, especially plov and manti.","question":24},{"voice":"man","text":"Where do your ingredients come from?"},{"voice":"woman","text":"I have a small garden, but it's only for herbs. Most of our vegetables come from local farmers. I know every one of them personally.","question":25},{"voice":"man","text":"What makes a good chef?"},{"voice":"woman","text":"Creativity and speed help, of course. But the most important skill is organisation. In a busy kitchen, if you're not organised, everything goes wrong.","question":26},{"voice":"man","text":"What are your plans?"},{"voice":"woman","text":"People keep asking me to open a second restaurant, but next year I'm going to write a cookbook with my grandmother's recipes.","question":27},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear a guide at a science centre. Complete the notes. Write one word or a number."},{"voice":"woman","text":"Hello, everyone, and welcome to the Science Centre. Before we start, please leave your bags in the cloakroom, next to the entrance.","question":28},{"voice":"woman","text":"Our first activity is the planetarium show. It lasts forty minutes, so please sit comfortably.","question":29},{"voice":"woman","text":"At one o'clock, we'll have lunch in the canteen on the ground floor. Please don't eat in the exhibition halls.","question":30},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a talk about saving money. Choose the correct answer."},{"voice":"man","text":"Hello, everyone. Why do so many people find it hard to save money? Most people think they don't earn enough. But the real reason is that they don't plan.","question":31},{"voice":"man","text":"So how much should you save? Don't wait to see what's left at the end of the month, because nothing will be left. Try to save ten percent of your income.","question":32},{"voice":"man","text":"And timing matters. The best moment to save is on payday. Move the money to a savings account before you start spending.","question":33},{"voice":"man","text":"Watch out for small daily purchases, like coffee or snacks. They seem harmless, but they're surprisingly expensive when you add them up over a year.","question":34},{"voice":"man","text":"My final advice: track your spending. Write down everything you buy for one month. You'll be amazed where your money goes. Thank you.","question":35},{"voice":"narrator","text":"That is the end of the listening test."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

insert into public.tests (id, number, title, format_month, format_year, is_new, is_free, is_pro, content)
values ('t11', 11, 'Mock Test #11', 8, 2026, false, true, false, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":3,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some short conversations. Choose the correct answer.","durationSec":150,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"What does the man want to buy?","options":[{"key":"A","text":"A jacket"},{"key":"B","text":"A pair of shoes"},{"key":"C","text":"A shirt"}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"Where will the friends meet?","options":[{"key":"A","text":"At the cinema"},{"key":"B","text":"At the bus stop"},{"key":"C","text":"At the park gate"}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"What is the woman’s new job?","options":[{"key":"A","text":"Teacher"},{"key":"B","text":"Nurse"},{"key":"C","text":"Accountant"}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"How will they get to the airport?","options":[{"key":"A","text":"By taxi"},{"key":"B","text":"By train"},{"key":"C","text":"By car"}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"What did the boy forget?","options":[{"key":"A","text":"His homework"},{"key":"B","text":"His lunch"},{"key":"C","text":"His sports kit"}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"When is the concert?","options":[{"key":"A","text":"On Friday"},{"key":"B","text":"On Saturday"},{"key":"C","text":"On Sunday"}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"What is wrong with the room?","options":[{"key":"A","text":"It is too small"},{"key":"B","text":"It is noisy"},{"key":"C","text":"It is cold"}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"How many people are coming to dinner?","options":[{"key":"A","text":"Four"},{"key":"B","text":"Six"},{"key":"C","text":"Eight"}]}],"audio":"t11/l1.mp3","audioAt":{"1":8,"2":28,"3":44,"4":61,"5":81,"6":100,"7":115,"8":129}},{"id":"l2","index":2,"title":"Sunrise Fitness Club — New Members","instruction":"Complete the notes. Write","emphasis":"no more than two words","durationSec":91,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"Opening time on weekdays:"},{"id":"l-10","number":10,"kind":"gap","prompt":"Monthly fee: £"},{"id":"l-11","number":11,"kind":"gap","prompt":"Joining requires a recent"},{"id":"l-12","number":12,"kind":"gap","prompt":"First personal training session is"},{"id":"l-13","number":13,"kind":"gap","prompt":"Yoga classes take place on"},{"id":"l-14","number":14,"kind":"gap","prompt":"Lockers are next to the"},{"id":"l-15","number":15,"kind":"gap","prompt":"Members should bring a"},{"id":"l-16","number":16,"kind":"gap","prompt":"Car park is at the"}],"audio":"t11/l2.mp3","audioAt":{"9":17,"10":28,"11":38,"12":43,"13":52,"14":62,"15":68,"16":75}},{"id":"l3","index":3,"instruction":"You will hear six people talking about their holidays. Choose the correct answer.","durationSec":87,"questions":[{"id":"l-17","number":17,"kind":"mcq","prompt":"Speaker 1 enjoyed her holiday mainly because of","options":[{"key":"A","text":"the food"},{"key":"B","text":"the people"},{"key":"C","text":"the beaches"}]},{"id":"l-18","number":18,"kind":"mcq","prompt":"Speaker 2 had a problem with","options":[{"key":"A","text":"his hotel"},{"key":"B","text":"his luggage"},{"key":"C","text":"the weather"}]},{"id":"l-19","number":19,"kind":"mcq","prompt":"Speaker 3 travelled","options":[{"key":"A","text":"alone"},{"key":"B","text":"with friends"},{"key":"C","text":"with her family"}]},{"id":"l-20","number":20,"kind":"mcq","prompt":"Speaker 4 prefers holidays","options":[{"key":"A","text":"in the mountains"},{"key":"B","text":"by the sea"},{"key":"C","text":"in big cities"}]},{"id":"l-21","number":21,"kind":"mcq","prompt":"Speaker 5 says his trip was","options":[{"key":"A","text":"too expensive"},{"key":"B","text":"too short"},{"key":"C","text":"too tiring"}]},{"id":"l-22","number":22,"kind":"mcq","prompt":"Speaker 6 wants to go back to learn","options":[{"key":"A","text":"the language"},{"key":"B","text":"to cook"},{"key":"C","text":"to dive"}]}],"audio":"t11/l3.mp3","audioAt":{"17":9,"18":23,"19":37,"20":49,"21":61,"22":71}},{"id":"l4","index":4,"instruction":"Listen to an interview with a university librarian. Choose the correct answer.","durationSec":74,"questions":[{"id":"l-23","number":23,"kind":"mcq","prompt":"The librarian says students today mostly use the library to","options":[{"key":"A","text":"borrow books"},{"key":"B","text":"study in groups"},{"key":"C","text":"print documents"}]},{"id":"l-24","number":24,"kind":"mcq","prompt":"The biggest change in recent years has been","options":[{"key":"A","text":"longer opening hours"},{"key":"B","text":"digital resources"},{"key":"C","text":"a new building"}]},{"id":"l-25","number":25,"kind":"mcq","prompt":"What do students complain about most?","options":[{"key":"A","text":"Noise"},{"key":"B","text":"The Wi-Fi"},{"key":"C","text":"The lack of seats"}]},{"id":"l-26","number":26,"kind":"mcq","prompt":"The library plans to","options":[{"key":"A","text":"open a café"},{"key":"B","text":"build a quiet floor"},{"key":"C","text":"stay open all night"}]},{"id":"l-27","number":27,"kind":"mcq","prompt":"She thinks paper books will","options":[{"key":"A","text":"disappear soon"},{"key":"B","text":"remain important"},{"key":"C","text":"become more expensive"}]}],"audio":"t11/l4.mp3","audioAt":{"23":16,"24":26,"25":37,"26":49,"27":60}},{"id":"l5","index":5,"title":"Old Town Walking Tour","instruction":"Complete the notes. Write","emphasis":"one word or a number","durationSec":42,"questions":[{"id":"l-28","number":28,"kind":"gap","prompt":"Tour meeting point: the old"},{"id":"l-29","number":29,"kind":"gap","prompt":"Number of stops on the tour:"},{"id":"l-30","number":30,"kind":"gap","prompt":"Tour finishes at the"}],"audio":"t11/l5.mp3","audioAt":{"28":10,"29":20,"30":31}},{"id":"l6","index":6,"instruction":"Listen to a lecture about social media. Choose the correct answer.","durationSec":66,"questions":[{"id":"l-31","number":31,"kind":"mcq","prompt":"On average, young people spend on social media","options":[{"key":"A","text":"one hour a day"},{"key":"B","text":"three hours a day"},{"key":"C","text":"six hours a day"}]},{"id":"l-32","number":32,"kind":"mcq","prompt":"The lecturer says the main risk is","options":[{"key":"A","text":"losing sleep"},{"key":"B","text":"comparing ourselves to others"},{"key":"C","text":"sharing personal data"}]},{"id":"l-33","number":33,"kind":"mcq","prompt":"Social media can be positive when it helps people","options":[{"key":"A","text":"earn money"},{"key":"B","text":"stay in touch"},{"key":"C","text":"learn to code"}]},{"id":"l-34","number":34,"kind":"mcq","prompt":"In the study, students who took a break felt","options":[{"key":"A","text":"bored"},{"key":"B","text":"happier"},{"key":"C","text":"more stressed"}]},{"id":"l-35","number":35,"kind":"mcq","prompt":"The lecturer recommends","options":[{"key":"A","text":"deleting all apps"},{"key":"B","text":"turning off notifications"},{"key":"C","text":"using only one app"}]}],"audio":"t11/l6.mp3","audioAt":{"31":7,"32":18,"33":31,"34":40,"35":50}}],"reading":[{"id":"r1","index":1,"title":"Notice: City Swimming Competition","instruction":"Read the text and fill in the gaps. Write one word only.","passage":[{"label":"A","text":"The City Swimming Competition for young people aged ten to sixteen will be held at the Olympic Pool on 3 June. Registration closes on 20 May."},{"label":"B","text":"Each swimmer may enter up to three races. The registration fee is five pounds, and all participants will receive a free T-shirt."},{"label":"C","text":"Parents are welcome to watch from the upper seating area. Please note that photography near the pool is not allowed."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"The competition takes place at the Olympic"},{"id":"r-2","number":2,"kind":"gap","prompt":"The oldest swimmers can be"},{"id":"r-3","number":3,"kind":"gap","prompt":"Registration ends in"},{"id":"r-4","number":4,"kind":"gap","prompt":"A swimmer can enter a maximum of three"},{"id":"r-5","number":5,"kind":"gap","prompt":"Every participant gets a free"},{"id":"r-6","number":6,"kind":"gap","prompt":"Parents sit in the upper seating"},{"id":"r-7","number":7,"kind":"gap","prompt":"Taking photos near the pool is not"}]},{"id":"r2","index":2,"title":"Short Messages","instruction":"Read the messages and choose the correct answer.","passage":[{"label":"A","text":"Hi Dilnoza! Mum’s birthday dinner is at 8 on Saturday at the Silk Road restaurant. I’ve ordered the cake — could you buy the flowers?"},{"label":"B","text":"Notice to residents: water will be switched off on Wednesday from 9 am to 1 pm while pipes are replaced."},{"label":"C","text":"Your order #4521 has been sent. It will arrive within three working days. You can track it on our website."}],"questions":[{"id":"r-8","number":8,"kind":"mcq","prompt":"What is the dinner for?","options":[{"key":"A","text":"A wedding"},{"key":"B","text":"A birthday"},{"key":"C","text":"A graduation"}]},{"id":"r-9","number":9,"kind":"mcq","prompt":"What should Dilnoza buy?","options":[{"key":"A","text":"A cake"},{"key":"B","text":"Flowers"},{"key":"C","text":"A present"}]},{"id":"r-10","number":10,"kind":"mcq","prompt":"Why will the water be switched off?","options":[{"key":"A","text":"To clean the tanks"},{"key":"B","text":"To replace pipes"},{"key":"C","text":"To save water"}]},{"id":"r-11","number":11,"kind":"mcq","prompt":"For how long will there be no water?","options":[{"key":"A","text":"Two hours"},{"key":"B","text":"Four hours"},{"key":"C","text":"All day"}]},{"id":"r-12","number":12,"kind":"mcq","prompt":"When will the order arrive?","options":[{"key":"A","text":"Tomorrow"},{"key":"B","text":"Within three working days"},{"key":"C","text":"Next week"}]},{"id":"r-13","number":13,"kind":"mcq","prompt":"How can the customer check the delivery?","options":[{"key":"A","text":"By phone"},{"key":"B","text":"On the website"},{"key":"C","text":"By email"}]},{"id":"r-14","number":14,"kind":"mcq","prompt":"Which message is from a family member?","options":[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"}]}]},{"id":"r3","index":3,"title":"Learning a Language as an Adult","instruction":"Read the article and choose the correct answer.","passage":[{"label":"A","text":"Many adults believe they are too old to learn a new language. Research, however, shows that adults can learn grammar and vocabulary faster than children."},{"label":"B","text":"What children do better is pronunciation. Young learners often develop a native-like accent, which is much harder for adults."},{"label":"C","text":"Experts say the key for adults is regular practice. Twenty minutes a day is more effective than two hours once a week."},{"label":"D","text":"Motivation also matters. Adults who learn a language for a clear reason, such as a job or travel, usually make faster progress."}],"questions":[{"id":"r-15","number":15,"kind":"mcq","prompt":"Many adults wrongly believe that they","options":[{"key":"A","text":"learn slowly"},{"key":"B","text":"are too old to learn"},{"key":"C","text":"need a teacher"}]},{"id":"r-16","number":16,"kind":"mcq","prompt":"Adults learn faster than children in","options":[{"key":"A","text":"grammar and vocabulary"},{"key":"B","text":"pronunciation"},{"key":"C","text":"listening"}]},{"id":"r-17","number":17,"kind":"mcq","prompt":"Children are better at","options":[{"key":"A","text":"reading"},{"key":"B","text":"accent"},{"key":"C","text":"writing"}]},{"id":"r-18","number":18,"kind":"mcq","prompt":"Experts recommend","options":[{"key":"A","text":"long lessons"},{"key":"B","text":"short daily practice"},{"key":"C","text":"weekend courses"}]},{"id":"r-19","number":19,"kind":"mcq","prompt":"Which learners usually progress faster?","options":[{"key":"A","text":"Those with a clear reason"},{"key":"B","text":"Those who study grammar"},{"key":"C","text":"Those who travel often"}]},{"id":"r-20","number":20,"kind":"mcq","prompt":"The word “effective” is closest to","options":[{"key":"A","text":"successful"},{"key":"B","text":"difficult"},{"key":"C","text":"expensive"}]},{"id":"r-21","number":21,"kind":"mcq","prompt":"The best title is","options":[{"key":"A","text":"Never Too Late"},{"key":"B","text":"Why Children Learn Faster"},{"key":"C","text":"The Perfect Accent"}]}]},{"id":"r4","index":4,"title":"The Aral Sea: A Story of Loss and Hope","instruction":"Do the following statements agree with the information in the text?","passage":[{"label":"A","text":"Once the fourth-largest lake in the world, the Aral Sea began to shrink in the 1960s, when rivers that fed it were used to water cotton fields."},{"label":"B","text":"By the 2000s, the sea had split into several smaller lakes, and many fishing towns found themselves far from the water."},{"label":"C","text":"In 2005, a dam was built to protect the northern part of the sea. Since then, water levels there have risen and some fish have returned.","highlight":"water levels there have risen and some fish have returned"},{"label":"D","text":"Scientists are now planting desert plants on the dry seabed to stop salt and dust from spreading to nearby villages."}],"questions":[{"id":"r-22","number":22,"kind":"tfng","prompt":"The Aral Sea started to shrink in the 1960s."},{"id":"r-23","number":23,"kind":"tfng","prompt":"The rivers were used to produce electricity."},{"id":"r-24","number":24,"kind":"tfng","prompt":"The northern part of the sea has improved since 2005."},{"id":"r-25","number":25,"kind":"tfng","prompt":"The dam cost more than one billion dollars."},{"id":"r-26","number":26,"kind":"tfng","prompt":"Plants are being grown on the dry seabed."}]},{"id":"r5","index":5,"title":"The Power of Walking","instruction":"Read the text and choose the correct answer.","passage":[{"label":"A","text":"Walking is one of the simplest ways to stay healthy. Doctors recommend around seven thousand steps a day, not ten thousand as many people think."},{"label":"B","text":"A thirty-minute walk can improve mood, reduce stress and even help people sleep better at night."},{"label":"C","text":"Walking also helps creativity. In one study, people came up with sixty percent more ideas while walking than while sitting."},{"label":"D","text":"Best of all, walking is free and needs no special equipment — just a comfortable pair of shoes."}],"questions":[{"id":"r-27","number":27,"kind":"mcq","prompt":"How many steps do doctors recommend?","options":[{"key":"A","text":"5,000"},{"key":"B","text":"7,000"},{"key":"C","text":"10,000"}]},{"id":"r-28","number":28,"kind":"mcq","prompt":"The number “ten thousand” is described as","options":[{"key":"A","text":"a scientific fact"},{"key":"B","text":"a common belief"},{"key":"C","text":"the minimum"}]},{"id":"r-29","number":29,"kind":"mcq","prompt":"A thirty-minute walk can help people to","options":[{"key":"A","text":"lose weight quickly"},{"key":"B","text":"sleep better"},{"key":"C","text":"build muscles"}]},{"id":"r-30","number":30,"kind":"mcq","prompt":"In the study, walking increased ideas by","options":[{"key":"A","text":"16%"},{"key":"B","text":"40%"},{"key":"C","text":"60%"}]},{"id":"r-31","number":31,"kind":"mcq","prompt":"What equipment does walking need?","options":[{"key":"A","text":"None except shoes"},{"key":"B","text":"A fitness watch"},{"key":"C","text":"Special clothes"}]},{"id":"r-32","number":32,"kind":"mcq","prompt":"The word “reduce” is closest to","options":[{"key":"A","text":"increase"},{"key":"B","text":"lower"},{"key":"C","text":"cause"}]},{"id":"r-33","number":33,"kind":"mcq","prompt":"Paragraph C is mainly about","options":[{"key":"A","text":"health"},{"key":"B","text":"creativity"},{"key":"C","text":"cost"}]},{"id":"r-34","number":34,"kind":"mcq","prompt":"The writer’s attitude to walking is","options":[{"key":"A","text":"critical"},{"key":"B","text":"neutral"},{"key":"C","text":"enthusiastic"}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"The main idea of the text is that walking","options":[{"key":"A","text":"is easy and beneficial"},{"key":"B","text":"is boring"},{"key":"C","text":"is only for older people"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1.1","kind":"Informal letter","context":"You and your friends are planning a trip to Samarkand next month. You have received this message from the travel agency:\n\n\"Unfortunately, the hotel you booked is no longer available. We can offer you a hotel outside the city centre at the same price, or return your money.\"","prompt":"Write a message to a friend who is going on the trip with you. Tell them about the news and say which option you prefer and why. Write about 50 words.","targetWords":50,"minWords":40},{"id":"w2","index":2,"label":"Task 1.2","kind":"Formal letter","context":"You and your friends are planning a trip to Samarkand next month. You have received this message from the travel agency:\n\n\"Unfortunately, the hotel you booked is no longer available. We can offer you a hotel outside the city centre at the same price, or return your money.\"","prompt":"Write a letter to the travel agency manager. Say how you feel about the situation, which option you choose and what else you expect from the agency. Write 120–150 words.","targetWords":135,"minWords":120},{"id":"w3","index":3,"label":"Task 2","kind":"Essay","prompt":"Some people say that it is better to live in a big city, while others prefer life in a small town or village. Discuss both views and give your own opinion. Write at least 180 words.","targetWords":200,"minWords":180}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"What do you do? Do you work or study?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"How do you usually travel around your city?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"What was the last film or series you watched?","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: students studying together in a library · Picture B: a student studying alone at home with a laptop","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Do you prefer studying alone or with other people? Why?","image":"Picture A: students studying together in a library · Picture B: a student studying alone at home with a laptop","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"How has technology changed the way students study?","image":"Picture A: students studying together in a library · Picture B: a student studying alone at home with a laptop","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe an older person you admire. Say who they are, what they have done and why you admire them.","image":"An old man telling stories to his grandchildren","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Mobile phones should be banned in schools. For: phones distract students and cause cheating. Against: phones are useful for learning and for safety. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
