insert into public.test_keys (test_id, keys, scripts)
values ('t13', $json${"l-1":{"answer":"B","explanation":"Ayol \"let's just meet at the station\" deydi."},"l-2":{"answer":"C","explanation":"Film 6:45 da emas, reklamadan keyin 7:15 da boshlanadi."},"l-3":{"answer":"A","explanation":"Velosiped ta'mirda, mashina esa xotinida — shuning uchun avtobus."},"l-4":{"answer":"B","explanation":"Qiz \"I've got the notebooks already\" deydi — kerakligi kalkulyator."},"l-5":{"answer":"B"},"l-6":{"answer":"C","explanation":"Sho'rva tugagan, shuning uchun salat buyuradi."},"l-7":{"answer":"A"},"l-8":{"answer":"B","explanation":"Narx £20, lekin talabalar uchun £5 chegirma bor."},"l-9":{"answer":"7 pm|7 p.m.|7pm"},"l-10":{"answer":"35","explanation":"Spiker avval \"forty-five\" deydi, keyin talabalar uchun \"ten pounds off\" chegirmani qo'shadi."},"l-11":{"answer":"passport"},"l-12":{"answer":"eight|8"},"l-13":{"answer":"0.50|0.5","explanation":"\"Fifty pence\" — 0.50 funt. \"Fifteen\" bilan adashtirmang."},"l-14":{"answer":"second floor"},"l-15":{"answer":"CV writing"},"l-16":{"answer":"email"},"l-17":{"answer":"B"},"l-18":{"answer":"A"},"l-19":{"answer":"B"},"l-20":{"answer":"C"},"l-21":{"answer":"B","explanation":"\"Hands-on\" iborasi amaliy degan ma'noni beradi."},"l-22":{"answer":"A"},"l-23":{"answer":"A"},"l-24":{"answer":"B"},"l-25":{"answer":"A"},"l-26":{"answer":"B"},"l-27":{"answer":"B"},"l-28":{"answer":"entrance"},"l-29":{"answer":"90|ninety"},"l-30":{"answer":"gallery","explanation":"Spiker \"except in the gallery\" deydi."},"l-31":{"answer":"B"},"l-32":{"answer":"B"},"l-33":{"answer":"B"},"l-34":{"answer":"B"},"l-35":{"answer":"C"},"r-1":{"answer":"months"},"r-2":{"answer":"day"},"r-3":{"answer":"adult"},"r-4":{"answer":"nothing"},"r-5":{"answer":"lock"},"r-6":{"answer":"reception"},"r-7":{"answer":"pool"},"r-8":{"answer":"B"},"r-9":{"answer":"B"},"r-10":{"answer":"B"},"r-11":{"answer":"B"},"r-12":{"answer":"B"},"r-13":{"answer":"B"},"r-14":{"answer":"A"},"r-15":{"answer":"B"},"r-16":{"answer":"B"},"r-17":{"answer":"B"},"r-18":{"answer":"A"},"r-19":{"answer":"A"},"r-20":{"answer":"B"},"r-21":{"answer":"B"},"r-22":{"answer":"False"},"r-23":{"answer":"False","explanation":"C paragrafda \"city bees often produce more honey\" deyilgan — ya'ni aksincha."},"r-24":{"answer":"True"},"r-25":{"answer":"Not given"},"r-26":{"answer":"True"},"r-27":{"answer":"B"},"r-28":{"answer":"B"},"r-29":{"answer":"B"},"r-30":{"answer":"C"},"r-31":{"answer":"B"},"r-32":{"answer":"A"},"r-33":{"answer":"B"},"r-34":{"answer":"B"},"r-35":{"answer":"B"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some short conversations. For each question, choose the correct answer."},{"voice":"narrator","text":"Question 1. Where does the woman want to meet?","question":1},{"voice":"man","text":"Shall we meet at the café before the concert? The one next to the library?"},{"voice":"woman","text":"Hmm, it's always so crowded on Fridays, and the library closes early anyway. Let's just meet at the station. It's easier for both of us."},{"voice":"man","text":"Fine. I'll be by the ticket machines."},{"voice":"narrator","text":"Question 2. What time does the film start?","question":2},{"voice":"woman","text":"The website says six forty-five. We should leave now."},{"voice":"man","text":"That's when the doors open, but there are always half an hour of adverts first. The film itself doesn't start until seven fifteen."},{"voice":"woman","text":"Oh, then we've got time for a coffee."},{"voice":"narrator","text":"Question 3. How will the man travel to work tomorrow?","question":3},{"voice":"woman","text":"Are you cycling to work tomorrow?"},{"voice":"man","text":"I'd love to, but my bike is still at the repair shop. And my wife needs the car to visit her mother, so I'll have to take the bus."},{"voice":"narrator","text":"Question 4. What does the girl need to buy?","question":4},{"voice":"man2","text":"Have you got everything for the maths exam, Anna?"},{"voice":"woman2","text":"I've got the notebooks already, and I can borrow Tom's dictionary for English. But my calculator broke yesterday, so I need to get a new one."},{"voice":"narrator","text":"Question 5. Why is the shop closed?","question":5},{"voice":"woman","text":"That's strange. The shop is closed. It isn't a holiday today, is it?"},{"voice":"man","text":"No. Look at the sign on the door: closed for repairs. They're fixing the roof after the storm. The owner says they'll open again next Monday."},{"voice":"narrator","text":"Question 6. What does the man order?","question":6},{"voice":"man","text":"I'll have the tomato soup, please."},{"voice":"woman","text":"I'm sorry, the soup is finished. We have sandwiches or a chicken salad."},{"voice":"man","text":"I had a sandwich for lunch, so I'll take the salad, please."},{"voice":"narrator","text":"Question 7. Where did the woman leave her keys?","question":7},{"voice":"man","text":"Did you find your keys? Were they on your desk?"},{"voice":"woman","text":"I checked my desk and my bag twice. In the end they were in the car. I'd left them next to the gear stick."},{"voice":"narrator","text":"Question 8. How much does the ticket cost?","question":8},{"voice":"woman","text":"One ticket for the exhibition, please. How much is it?"},{"voice":"man","text":"It's twenty pounds, but if you're a student, you get five pounds off."},{"voice":"woman","text":"Great, here's my student card."},{"voice":"man","text":"So that's fifteen pounds, then."},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a phone call to Riverside Library. Complete the notes. Write no more than two words."},{"voice":"woman","text":"Good morning, Riverside Library. How can I help you?"},{"voice":"man","text":"Hello. I've just moved to the area and I'd like to become a member. Could you tell me about it?"},{"voice":"woman","text":"Of course. We're open every day. At weekends we close at five, and on weekdays we stay open until seven p.m.","question":9},{"voice":"man","text":"Great. And how much does membership cost?"},{"voice":"woman","text":"The normal fee is forty-five pounds a year. Are you a student? Students get ten pounds off, so it's thirty-five pounds a year.","question":10},{"voice":"man","text":"Yes, I'm at the university. What do I need to bring?"},{"voice":"woman","text":"Your student card isn't enough, I'm afraid. Please bring a copy of your passport, so we can check your identity.","question":11},{"voice":"man","text":"No problem. How many books can I borrow?"},{"voice":"woman","text":"You can have up to eight books at one time, and you can keep them for three weeks.","question":12},{"voice":"man","text":"And if I bring them back late?"},{"voice":"woman","text":"Then there's a fine of fifty pence for each day. Not fifteen, fifty pence.","question":13},{"voice":"man","text":"I see. Is there a place where I can study?"},{"voice":"woman","text":"Yes. The ground floor is for children, but there's a quiet study room on the second floor.","question":14},{"voice":"man","text":"Do you organise any events?"},{"voice":"woman","text":"We do. This month there's a free workshop on CV writing, every Thursday evening.","question":15},{"voice":"man","text":"Perfect. And can I search for books online?"},{"voice":"woman","text":"Yes. When you join, we'll send you a password for the online catalogue by email. We don't send it by post any more.","question":16},{"voice":"man","text":"Thank you very much. See you tomorrow."},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear six people talking about their jobs. For each speaker, choose the correct answer."},{"voice":"narrator","text":"Speaker 1.","question":17},{"voice":"woman","text":"The pay is fine, nothing special, and I hardly ever travel. But I work with a fantastic team. My colleagues are the reason I get up happily every morning."},{"voice":"narrator","text":"Speaker 2.","question":18},{"voice":"man","text":"I'm a nurse, so giving presentations or meeting deadlines isn't really an issue. The hard part is the night shifts. My body never gets used to working when everyone else is asleep."},{"voice":"narrator","text":"Speaker 3.","question":19},{"voice":"man2","text":"People are surprised that I'm an engineer now, because I studied teaching. But my first real job was as a journalist for a local newspaper. I wrote about technology, and that's how it all began."},{"voice":"narrator","text":"Speaker 4.","question":20},{"voice":"woman2","text":"I'm happy with my company and I don't want to move abroad. But one day I'd like to be my own boss. My dream is to start a small business selling handmade furniture."},{"voice":"narrator","text":"Speaker 5.","question":21},{"voice":"woman3","text":"My training lasted a whole year, and luckily the company paid for it. What I liked most was that it was so hands-on. We learned by actually doing the job, not just reading about it."},{"voice":"narrator","text":"Speaker 6.","question":22},{"voice":"man3","text":"My hours are long and not flexible at all, and some problems take weeks to solve. But when a family leaves my office with a solution, knowing I've helped people makes it all worth it."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear a radio interview with a gardening expert. Choose the correct answer."},{"voice":"man","text":"Welcome back to Green Hour. My guest today is Laura Hill, who writes about city gardening. Laura, how did it all start for you?"},{"voice":"woman","text":"It started when I was about six. My grandmother gave me a tiny corner of her garden, and I grew my first carrots there. I studied economics at university, but I never lost that love.","question":23},{"voice":"man","text":"Many listeners live in flats. Isn't space the biggest problem in the city?"},{"voice":"woman","text":"Everyone thinks so, and pollution is a worry too. But actually the main problem is the soil. City soil is often poor, full of stones and building waste, so plants simply can't grow well.","question":24},{"voice":"man","text":"So what should a complete beginner grow?"},{"voice":"woman","text":"Not tomatoes. They need a lot of care. And flowers can be disappointing at first. I always tell beginners to start with herbs, like mint or basil. They grow quickly in small pots.","question":25},{"voice":"man","text":"You also support community gardens. Why are they important?"},{"voice":"woman","text":"They cost very little and you rarely need official permission. But the real benefit is social. Community gardens bring neighbours together. People who never spoke before start sharing tools and advice.","question":26},{"voice":"man","text":"Wonderful. And you'll be back next week?"},{"voice":"woman","text":"Yes. I was going to talk about saving water, but so many listeners asked about compost that next week will be all about composting at home.","question":27},{"voice":"man","text":"Laura Hill, thank you."},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear a guide at the City Museum. Complete the notes. Write one word or a number."},{"voice":"woman","text":"Good morning, everyone, and welcome to the City Museum. Our guided tour starts here, at the main entrance, so please don't go to the side door by the shop.","question":28},{"voice":"woman","text":"The tour usually takes an hour and a half. That's ninety minutes, with a short break in the café halfway through.","question":29},{"voice":"woman","text":"You're welcome to take photos everywhere in the museum, except in the gallery, because the old paintings can be damaged by the flash.","question":30},{"voice":"woman","text":"Right, if everyone is ready, let's begin."},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a lecture about sleep. Choose the correct answer."},{"voice":"man","text":"Good afternoon. Today we're talking about sleep. Let's start with the most common question: how much do we really need? Some people claim six hours is enough, and a few like ten. But research shows that most adults need between seven and nine hours a night.","question":31},{"voice":"man","text":"Now, what about phones and tablets? Many people think screens give us bad dreams, or make us wake up at night. In fact, their main effect is on falling asleep. The light from the screen tells the brain it's still daytime.","question":32},{"voice":"man","text":"What about naps? A morning nap doesn't do much, and an evening nap can ruin your night. The most useful time for a short nap is after lunch, when energy naturally drops.","question":33},{"voice":"man","text":"Teenagers are a special case. Parents often complain that they're lazy. But teenagers' body clocks actually shift, so they tend to fall asleep later and wake up later. It isn't that they sleep less deeply.","question":34},{"voice":"man","text":"So, what's my final advice? Diet and exercise both matter, but the most important thing is routine. Go to bed and get up at the same time every day, even at weekends. Thank you.","question":35},{"voice":"narrator","text":"That is the end of the listening test."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

insert into public.tests (id, number, title, format_month, format_year, is_new, is_free, is_pro, content)
values ('t14', 14, 'Mock Test #14', 9, 2026, false, false, true, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":3,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some short conversations. Choose the correct answer.","durationSec":142,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"What is the woman looking for?","options":[{"key":"A","text":"Her glasses"},{"key":"B","text":"Her phone"},{"key":"C","text":"Her passport"}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"How will the man pay?","options":[{"key":"A","text":"In cash"},{"key":"B","text":"By card"},{"key":"C","text":"By bank transfer"}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"What does the boy want to be?","options":[{"key":"A","text":"A pilot"},{"key":"B","text":"A doctor"},{"key":"C","text":"A programmer"}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"Where did the woman go on Sunday?","options":[{"key":"A","text":"To the theatre"},{"key":"B","text":"To the mountains"},{"key":"C","text":"To a wedding"}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"What is the problem with the flat?","options":[{"key":"A","text":"The heating"},{"key":"B","text":"The windows"},{"key":"C","text":"The neighbours"}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"How long has the man been waiting?","options":[{"key":"A","text":"Ten minutes"},{"key":"B","text":"Twenty minutes"},{"key":"C","text":"Half an hour"}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"Which course will the woman take?","options":[{"key":"A","text":"Photography"},{"key":"B","text":"Painting"},{"key":"C","text":"Pottery"}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"When will the parcel arrive?","options":[{"key":"A","text":"Tomorrow morning"},{"key":"B","text":"Tomorrow afternoon"},{"key":"C","text":"On Friday"}]}],"audio":"t14/l1.mp3","audioAt":{"1":8,"2":26,"3":43,"4":58,"5":77,"6":90,"7":107,"8":123}},{"id":"l2","index":2,"title":"City Volunteers — Registration","instruction":"Complete the notes. Write","emphasis":"no more than two words","durationSec":84,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"Volunteer project: helping at the"},{"id":"l-10","number":10,"kind":"gap","prompt":"Minimum age:"},{"id":"l-11","number":11,"kind":"gap","prompt":"Hours per week:"},{"id":"l-12","number":12,"kind":"gap","prompt":"Volunteers usually work on"},{"id":"l-13","number":13,"kind":"gap","prompt":"Training session takes place on the"},{"id":"l-14","number":14,"kind":"gap","prompt":"Volunteers receive a free"},{"id":"l-15","number":15,"kind":"gap","prompt":"Contact person: Mrs"},{"id":"l-16","number":16,"kind":"gap","prompt":"Application form available on the"}],"audio":"t14/l2.mp3","audioAt":{"9":13,"10":19,"11":30,"12":37,"13":44,"14":52,"15":61,"16":70}},{"id":"l3","index":3,"instruction":"You will hear six people talking about moving to a new city. Choose the correct answer.","durationSec":95,"questions":[{"id":"l-17","number":17,"kind":"mcq","prompt":"Speaker 1 moved because of","options":[{"key":"A","text":"her studies"},{"key":"B","text":"her husband’s job"},{"key":"C","text":"the climate"}]},{"id":"l-18","number":18,"kind":"mcq","prompt":"Speaker 2 found it difficult to","options":[{"key":"A","text":"find a flat"},{"key":"B","text":"make friends"},{"key":"C","text":"learn the language"}]},{"id":"l-19","number":19,"kind":"mcq","prompt":"Speaker 3 misses","options":[{"key":"A","text":"his family"},{"key":"B","text":"the food"},{"key":"C","text":"the sea"}]},{"id":"l-20","number":20,"kind":"mcq","prompt":"Speaker 4 says the new city is","options":[{"key":"A","text":"cheaper"},{"key":"B","text":"safer"},{"key":"C","text":"more exciting"}]},{"id":"l-21","number":21,"kind":"mcq","prompt":"Speaker 5 got help from","options":[{"key":"A","text":"a colleague"},{"key":"B","text":"a neighbour"},{"key":"C","text":"an online group"}]},{"id":"l-22","number":22,"kind":"mcq","prompt":"Speaker 6 plans to","options":[{"key":"A","text":"stay forever"},{"key":"B","text":"move back home"},{"key":"C","text":"move again"}]}],"audio":"t14/l3.mp3","audioAt":{"17":10,"18":23,"19":39,"20":56,"21":67,"22":79}},{"id":"l4","index":4,"instruction":"Listen to an interview with a mountain guide. Choose the correct answer.","durationSec":82,"questions":[{"id":"l-23","number":23,"kind":"mcq","prompt":"The guide started climbing","options":[{"key":"A","text":"with his father"},{"key":"B","text":"at a sports club"},{"key":"C","text":"in the army"}]},{"id":"l-24","number":24,"kind":"mcq","prompt":"The most dangerous thing in the mountains is","options":[{"key":"A","text":"the cold"},{"key":"B","text":"sudden weather changes"},{"key":"C","text":"wild animals"}]},{"id":"l-25","number":25,"kind":"mcq","prompt":"Beginners often make the mistake of","options":[{"key":"A","text":"carrying too much"},{"key":"B","text":"walking too fast"},{"key":"C","text":"not drinking enough"}]},{"id":"l-26","number":26,"kind":"mcq","prompt":"His favourite season for climbing is","options":[{"key":"A","text":"spring"},{"key":"B","text":"summer"},{"key":"C","text":"autumn"}]},{"id":"l-27","number":27,"kind":"mcq","prompt":"He thinks mountain tourism should","options":[{"key":"A","text":"be limited"},{"key":"B","text":"grow quickly"},{"key":"C","text":"be free"}]}],"audio":"t14/l4.mp3","audioAt":{"23":13,"24":24,"25":40,"26":51,"27":65}},{"id":"l5","index":5,"title":"University Open Day","instruction":"Complete the notes. Write","emphasis":"one word or a number","durationSec":34,"questions":[{"id":"l-28","number":28,"kind":"gap","prompt":"Welcome talk takes place in the"},{"id":"l-29","number":29,"kind":"gap","prompt":"Campus tours start every (minutes):"},{"id":"l-30","number":30,"kind":"gap","prompt":"Free lunch tickets are given at"}],"audio":"t14/l5.mp3","audioAt":{"28":10,"29":17,"30":23}},{"id":"l6","index":6,"instruction":"Listen to a lecture about climate and cities. Choose the correct answer.","durationSec":70,"questions":[{"id":"l-31","number":31,"kind":"mcq","prompt":"Cities are hotter than the countryside mainly because of","options":[{"key":"A","text":"traffic"},{"key":"B","text":"concrete and asphalt"},{"key":"C","text":"factories"}]},{"id":"l-32","number":32,"kind":"mcq","prompt":"The difference in temperature can be up to","options":[{"key":"A","text":"2 degrees"},{"key":"B","text":"5 degrees"},{"key":"C","text":"10 degrees"}]},{"id":"l-33","number":33,"kind":"mcq","prompt":"Green roofs help by","options":[{"key":"A","text":"producing food"},{"key":"B","text":"cooling buildings"},{"key":"C","text":"collecting rain"}]},{"id":"l-34","number":34,"kind":"mcq","prompt":"According to the lecturer, the cheapest solution is","options":[{"key":"A","text":"planting trees"},{"key":"B","text":"painting roofs white"},{"key":"C","text":"building fountains"}]},{"id":"l-35","number":35,"kind":"mcq","prompt":"The lecturer believes that cities should","options":[{"key":"A","text":"stop growing"},{"key":"B","text":"plan for heat now"},{"key":"C","text":"move industry outside"}]}],"audio":"t14/l6.mp3","audioAt":{"31":8,"32":25,"33":34,"34":45,"35":54}}],"reading":[{"id":"r1","index":1,"title":"Notice: New Library Rules","instruction":"Read the text and fill in the gaps. Write one word only.","passage":[{"label":"A","text":"From 1 September, the university library will be open 24 hours a day during the exam period. Students must show their ID card at the entrance after 10 pm."},{"label":"B","text":"Food is not allowed in the reading rooms, but drinks in bottles with lids are permitted. The café on the ground floor will stay open until midnight."},{"label":"C","text":"Group study rooms must be booked online at least one day in advance, and each booking is limited to two hours."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"The library will open all night during the exam"},{"id":"r-2","number":2,"kind":"gap","prompt":"After 10 pm, students must show their ID"},{"id":"r-3","number":3,"kind":"gap","prompt":"Students cannot bring food into the reading"},{"id":"r-4","number":4,"kind":"gap","prompt":"Drinks are allowed in bottles with"},{"id":"r-5","number":5,"kind":"gap","prompt":"The café closes at"},{"id":"r-6","number":6,"kind":"gap","prompt":"Group rooms must be booked"},{"id":"r-7","number":7,"kind":"gap","prompt":"A booking cannot be longer than two"}]},{"id":"r2","index":2,"title":"Short Messages","instruction":"Read the messages and choose the correct answer.","passage":[{"label":"A","text":"Team, the client presentation is now on Wednesday at 3, not Thursday. Please send me your slides by Tuesday evening."},{"label":"B","text":"Your flight HY 604 to Istanbul has been delayed by two hours. The new departure time is 16:40. We apologise for the inconvenience."},{"label":"C","text":"Aunt Gulnora, thank you for the beautiful scarf! I wore it to the concert last night and everyone asked where I got it."}],"questions":[{"id":"r-8","number":8,"kind":"mcq","prompt":"When is the presentation now?","options":[{"key":"A","text":"Tuesday"},{"key":"B","text":"Wednesday"},{"key":"C","text":"Thursday"}]},{"id":"r-9","number":9,"kind":"mcq","prompt":"What should the team send?","options":[{"key":"A","text":"Reports"},{"key":"B","text":"Slides"},{"key":"C","text":"Photos"}]},{"id":"r-10","number":10,"kind":"mcq","prompt":"How long is the flight delay?","options":[{"key":"A","text":"One hour"},{"key":"B","text":"Two hours"},{"key":"C","text":"Four hours"}]},{"id":"r-11","number":11,"kind":"mcq","prompt":"What is the new departure time?","options":[{"key":"A","text":"14:40"},{"key":"B","text":"16:40"},{"key":"C","text":"18:40"}]},{"id":"r-12","number":12,"kind":"mcq","prompt":"Why is the writer of message C thanking her aunt?","options":[{"key":"A","text":"For a concert ticket"},{"key":"B","text":"For a scarf"},{"key":"C","text":"For a dinner"}]},{"id":"r-13","number":13,"kind":"mcq","prompt":"Where did the writer wear the gift?","options":[{"key":"A","text":"To work"},{"key":"B","text":"To a concert"},{"key":"C","text":"To a wedding"}]},{"id":"r-14","number":14,"kind":"mcq","prompt":"Which message is from a company to a customer?","options":[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"}]}]},{"id":"r3","index":3,"title":"The Four-Day Working Week","instruction":"Read the article and choose the correct answer.","passage":[{"label":"A","text":"In recent trials, dozens of companies let their employees work four days a week for the same salary."},{"label":"B","text":"Most companies reported that productivity stayed the same or even increased, while staff took fewer sick days."},{"label":"C","text":"Not every business can adopt the idea. Hospitals, shops and factories that must stay open every day find it much harder."},{"label":"D","text":"Still, almost all companies in the trials decided to continue, suggesting that the idea may soon become more common."}],"questions":[{"id":"r-15","number":15,"kind":"mcq","prompt":"In the trials, employees","options":[{"key":"A","text":"earned less"},{"key":"B","text":"earned the same"},{"key":"C","text":"earned more"}]},{"id":"r-16","number":16,"kind":"mcq","prompt":"Productivity in most companies","options":[{"key":"A","text":"fell"},{"key":"B","text":"stayed the same or rose"},{"key":"C","text":"was not measured"}]},{"id":"r-17","number":17,"kind":"mcq","prompt":"Staff in the trials","options":[{"key":"A","text":"took fewer sick days"},{"key":"B","text":"worked longer hours"},{"key":"C","text":"changed jobs"}]},{"id":"r-18","number":18,"kind":"mcq","prompt":"Which businesses find the idea difficult?","options":[{"key":"A","text":"Offices"},{"key":"B","text":"Hospitals and shops"},{"key":"C","text":"Schools"}]},{"id":"r-19","number":19,"kind":"mcq","prompt":"After the trials, most companies","options":[{"key":"A","text":"stopped"},{"key":"B","text":"continued"},{"key":"C","text":"paid more"}]},{"id":"r-20","number":20,"kind":"mcq","prompt":"The word “adopt” is closest to","options":[{"key":"A","text":"reject"},{"key":"B","text":"start using"},{"key":"C","text":"study"}]},{"id":"r-21","number":21,"kind":"mcq","prompt":"The writer suggests the idea will","options":[{"key":"A","text":"fail"},{"key":"B","text":"become more common"},{"key":"C","text":"be banned"}]}]},{"id":"r4","index":4,"title":"Snow Leopards of Central Asia","instruction":"Do the following statements agree with the information in the text?","passage":[{"label":"A","text":"The snow leopard lives high in the mountains of Central Asia, including parts of Uzbekistan, Kyrgyzstan and Tajikistan."},{"label":"B","text":"Because it is shy and active mainly at dawn and dusk, it is very rarely seen, and scientists often call it the “ghost of the mountains”."},{"label":"C","text":"Camera traps have changed research completely. Hidden cameras now record animals that no scientist has ever seen in person.","highlight":"Camera traps have changed research completely"},{"label":"D","text":"Numbers fell in the past because of hunting, but thanks to protection programmes, the population in some areas is now stable."}],"questions":[{"id":"r-22","number":22,"kind":"tfng","prompt":"Snow leopards can be found in Uzbekistan."},{"id":"r-23","number":23,"kind":"tfng","prompt":"Snow leopards are mostly active in the middle of the day."},{"id":"r-24","number":24,"kind":"tfng","prompt":"Camera traps have transformed research on snow leopards."},{"id":"r-25","number":25,"kind":"tfng","prompt":"There are more than ten thousand snow leopards in the world."},{"id":"r-26","number":26,"kind":"tfng","prompt":"The population is now growing quickly everywhere."}]},{"id":"r5","index":5,"title":"Why Some Words Survive","instruction":"Read the text and choose the correct answer.","passage":[{"label":"A","text":"Every year, dictionaries add hundreds of new words, but only a few of them are still used ten years later."},{"label":"B","text":"Linguists have found that short words that describe something genuinely new, like “email”, are the most likely to survive."},{"label":"C","text":"Words based on jokes or famous events usually disappear quickly, because the situation that created them is soon forgotten."},{"label":"D","text":"Interestingly, the internet has made this process faster: words now appear and disappear within months rather than decades."}],"questions":[{"id":"r-27","number":27,"kind":"mcq","prompt":"How many new words do dictionaries add each year?","options":[{"key":"A","text":"A few"},{"key":"B","text":"Hundreds"},{"key":"C","text":"Millions"}]},{"id":"r-28","number":28,"kind":"mcq","prompt":"Which words are most likely to survive?","options":[{"key":"A","text":"Long technical words"},{"key":"B","text":"Short words for new things"},{"key":"C","text":"Words from jokes"}]},{"id":"r-29","number":29,"kind":"mcq","prompt":"“Email” is given as an example of a word that","options":[{"key":"A","text":"disappeared"},{"key":"B","text":"survived"},{"key":"C","text":"changed meaning"}]},{"id":"r-30","number":30,"kind":"mcq","prompt":"Words based on famous events usually","options":[{"key":"A","text":"last for decades"},{"key":"B","text":"disappear quickly"},{"key":"C","text":"become formal"}]},{"id":"r-31","number":31,"kind":"mcq","prompt":"The internet has made the life of new words","options":[{"key":"A","text":"longer"},{"key":"B","text":"shorter"},{"key":"C","text":"more formal"}]},{"id":"r-32","number":32,"kind":"mcq","prompt":"The word “genuinely” is closest to","options":[{"key":"A","text":"really"},{"key":"B","text":"rarely"},{"key":"C","text":"partly"}]},{"id":"r-33","number":33,"kind":"mcq","prompt":"Who studied the survival of words?","options":[{"key":"A","text":"Historians"},{"key":"B","text":"Linguists"},{"key":"C","text":"Journalists"}]},{"id":"r-34","number":34,"kind":"mcq","prompt":"The text is mainly about","options":[{"key":"A","text":"how new words live and die"},{"key":"B","text":"how to write dictionaries"},{"key":"C","text":"internet slang"}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"The writer finds the effect of the internet","options":[{"key":"A","text":"worrying"},{"key":"B","text":"interesting"},{"key":"C","text":"unimportant"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1.1","kind":"Informal letter","context":"You work for a company in Tashkent. You have received this email from your manager:\n\n\"Next month the company will move to a new office outside the city. The working day will start at 8 am instead of 9 am, and a free company bus will be provided.\"","prompt":"Write a message to a colleague. Tell them what you think about the news and how it will affect you. Write about 50 words.","targetWords":50,"minWords":40},{"id":"w2","index":2,"label":"Task 1.2","kind":"Formal letter","context":"You work for a company in Tashkent. You have received this email from your manager:\n\n\"Next month the company will move to a new office outside the city. The working day will start at 8 am instead of 9 am, and a free company bus will be provided.\"","prompt":"Write a letter to your manager. Explain how the changes will affect you and make suggestions to help employees. Write 120–150 words.","targetWords":135,"minWords":120},{"id":"w3","index":3,"label":"Task 2","kind":"Essay","prompt":"Some people think that governments should spend money on space exploration, while others believe this money should be used to solve problems on Earth. Discuss both views and give your opinion. Write at least 180 words.","targetWords":200,"minWords":180}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"What do you like about the place where you live?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"How do you usually celebrate your birthday?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"Do you like reading? What do you read?","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: a family on holiday at the beach · Picture B: a group of friends hiking in the mountains","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Which holiday would you prefer? Why?","image":"Picture A: a family on holiday at the beach · Picture B: a group of friends hiking in the mountains","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"Why do people need holidays?","image":"Picture A: a family on holiday at the beach · Picture B: a group of friends hiking in the mountains","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe a difficult challenge you have faced. Say what the challenge was, how you dealt with it and what you learned from it.","image":"A student giving a presentation in front of a class","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Children should start learning a foreign language in kindergarten. For: young children learn languages easily and naturally. Against: they should first master their own language. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
